def contains_proper_nouns(sentence):
    """
    Checks whether a sentence contains at least one proper noun.

    Args:
    - sentence (str): The input sentence.

    Returns:
    - bool: True if the sentence contains a proper noun, False otherwise.
    """

    # Convert the sentence to lowercase for case-insensitivity
    sentence = sentence.lower()

    proper_nouns = ['jackson', 'feline', 'thirteen', 'mittens']

    # Check each word in the sentence for proper nouns
    for word in sentence.split():
        if word in proper_nouns:
            return True

    return False


