public class ContainsProperNouns {

    public static boolean containsProperNouns(String sentence) {
        String[] properNouns = {"Jack", "feline", "thirteen", "Mittens"};

        String lowercaseSentence = sentence.toLowerCase();
        String[] words = lowercaseSentence.split(" ");

        for (String word : words) {
