import java.util.Arrays;

public class HyponymHypernym {

    public static String findHyponym(String word) {
        String[] possibleHyponyms = {
                "bout",
                "cayucos",
                "dory",
                "drascombe",
                "fleetwood",
                "gondola",
                "guldtacka",
                "kayap",
                "kayak",
                "kotter",
                "lapstrake",
                "louter",
                "motopya",
                "piragua",
                "prau",
                "scow",
                "shadúlka",
                "stroomlijnboten",
                "tarpan",
                "varza",
                "veselíček",
                "western river boat",
                "whitewater boat",
                "yole"
        };

        String hyponym = Arrays.stream(possibleHyponyms)
                                .filter(h -> h.compareTo(word) < 0)
                                .findFirst()
                                .orElse(null);

        if (hyponym != null) {
            return hyponym;
        } else {
            // if no hyponym is found, return the input word itself as the fallback
            return word;
        }
    }

    public static String findHypernym(String word) {
        String[] possibleHypernyms = {"watercraft", "craft", "boat", "vessel"};

        String hypernym = Arrays.stream(possibleHypernyms)
                                 .filter(h -> h.compareTo(word) > 0)
                                 .findFirst()
                                 .orElse(null);

        if (hypernym != null) {
            return hypernym;
        } else {
            // if no hypernym is found, return the input word itself as the fallback
            return word;
        }
    }

    public static void main(String[] args) {
        String word = "paddlecraft";
        String hyponym = findHyponym(word);
        String hypernym = findHypernym(hyponym);
        System.out.printf("The hyponym of '%s' is: %s%n", word, hyponym);
        System.out.printf("The hyponym relates to: %s%n", hypernym);

        String hyponym2 = "dory";
        String hypernym2 = findHypernym(hyponym2);
        System.out.printf("The hypernym of '%s' is: %s%n", hyponym2, hypernym2);
    }
}

