# example function to generate hypernym for a given concept word

def generate_hypernym(concept_word: str) -> str:
    # load wordnet
    import nltk
    from nltk.corpus import wordnet

    # synsets for the concept word
    synsets = wordnet.synsets(concept_word)

    # check if any synsets exist
    if not synsets:
        return "No synsets found for the given concept word."

    # synset with the most generic definition - hypernym
    max_depth = float('-inf')
    hypernym = ""
    for synset in synsets:
        if synset.hypernym_count() > max_depth:
            max_depth = synset.hypernym_count()
            hypernym = synset.name().split('.')[0]

    return hypernym


