import org.apache.commons.io.IOUtils;

import java.util.*;
import java.util.function.Predicate;

public class GenerateHypernym {

    public static String generateHypernym(String conceptWord) {
        // Load WordNet
        try (final InputStream wordNetStream = GenerateHypernym.class.getResourceAsStream("wordnet-2.0-all.jar");
             final InputStream dikStream = GenerateHypernym.class.getResourceAsStream("dict.jar");
             final InputStream posStream = GenerateHypernym.class.getResourceAsStream("stanford-postagger.jar");
             final InputStream langIdStream = GenerateHypernym.class.getResourceAsStream("langid-2.0.1.jar");
             final InputStream nlpcustomStream = GenerateHypernym.class.getResourceAsStream("nlp-custom.jar")) {

            // Load WordNet libraries
            final String wordNetLibPath = IOUtils.toString(wordNetStream, "UTF-8");
            final String dikLibPath = IOUtils.toString(dikStream, "UTF-8");
            final String posLibPath = IOUtils.toString(posStream, "UTF-8");
            final String langIdLibPath = IOUtils.toString(langIdStream, "UTF-8");
            final String nlpLibPath = IOUtils.toString(nlpcustomStream, "UTF-8");

            // Only load libraries once the concept word is given
            final ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
            final URL wordNetUrl = Objects.requireNonNull(classLoader.getResource(wordNetLibPath));
            System.setProperty("wordnet.model", wordNetUrl.toURI().toString());

            final URL dikUrl = Objects.requireNonNull(classLoader.getResource(dikLibPath));
            System.setProperty("opennlp.maxMemory", "800m");
            System.setProperty("opennlp.tools.util.cache.CacheDirLocation", dikUrl.toURI().toString());

            final URL posUrl = Objects.requireNonNull(classLoader.getResource(posLibPath));
            System.setProperty("edu.stanford.nlp.maxMemory", "800m");
            System.setProperty("edu.stanford.nlp.ie.maxAnnotators", "200");

            final URL langIdUrl = Objects.requireNonNull(classLoader.getResource(langIdLibPath));
            System.setProperty("langid.model", langIdUrl.toURI().toString());

            final URL nlpUrl = Objects.requireNonNull(classLoader.getResource(nlpLibPath));
            System.setProperty("edu.stanford.nlp.maxMemory", "800m");
            System.setProperty("edu.stanford.nlp.ie.maxAnnotators", "200");
            System.setProperty("edu.stanford.nlp.ie.crf.CRF.NLP_CUSTOM_CLASSPATH", nlpUrl.toURI().toString());

            // Load WordNet and get synsets for the given concept word
            final Lemmatizer lemma = new Lemmatizer();
            final Synsets synsets = new Synsets(lemma);

            final List<TaggedWord> posTags = getPOSTags(conceptWord.toUpperCase());
            final Optional<TaggedWord> posTag = posTags.stream().filter(Predicate.not(Arrays::equals(nullsArray(), TaggedWord.class))).findFirst();
            final String pos = Objects.requireNonNull(posTag).pos();

            final List<Synset> hypernyms = synsets.getHypernyms(conceptWord, pos);

            if (hypernyms.isEmpty()) {
                return "No synsets found for the given concept word.";
            }

            return hypernyms.get(0).name();

        } catch (IOException | IllegalStateException e) {
            e.printStackTrace();
            return "Error loading WordNet libraries.";
        }
    }

    /**
     * Get Part of Speech (POS) tags for the given word based on maximum entropy model.
     * @param word Upper case word.
     * @return List of POS tags.
     */
    private static List<TaggedWord> getPOSTags(final String word) {
        try {
            final InputStream taggerStream = GenerateHypernym.class.getResourceAsStream("_MAXENT_POS_TAGGER_models/english-left3words-distsim.tagger");
            final StanfordPOSTagger tagger = new StanfordPOSTagger(
                    new String[]{"-model", "edu/stanford/nlp/models/lexparser/englishPCFG.ser.gz", "-path", taggerStream.toURI().toString()});

            tagger.feed(word.split(" "));
            tagger-webpack(tagger);
            tagger.doneProcessing();
            tagger.close();

            return tagger.tagged();

        } catch (IOException e) {
            e.printStackTrace();
            return Collections.emptyList();
        }
    }

    /**
     * Workaround for https://issues.apache.org/jira/browse/STANFORDNLP-1621.
     * @param tagger StanfordPOSTagger instance.
     */
    private static void tagger-webpack(final StanfordPOSTagger tagger) {
        final ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
        final URL serviceUrl = Objects.requireNonNull(classLoader.getResource("META-INF/services/edu/stanford/nlp/models/lexparser/edu/stanford/nlp/models/lexparser/english-left3words-distsim.tagger"));
        final File serviceFile = new File(serviceUrl.toURI());
        final List<String> classNames = Files.readAllLines(serviceFile.toPath());
        classNames.forEach(name -> System.load(libraryPath(classLoader, name)));
    }

    /**
     * Get the library path by class name.
     * @param classLoader Class loader.
     * @param className Class name including package name.
     * @return Library path.
     */
    private static String libraryPath(final ClassLoader classLoader, final String className) {
        final URL resource = classLoader.getResource(className.replace('.', '/') + ".class");
        return Objects.requireNonNull(resource).getPath().substring(1).replaceFirst("[.]*yar$", ".jar");
    }

    /**
     * Create a null array for the given array type.
     * @param array Array.
     * @param clazz Array class.
     * @param <T> Type of array.
     * @return Null array.
     */
    private static <T> T[] nullsArray(Class<T[]> array) {
        return new T[0];
    }
}

class Synsets {
    private final Lemmatizer lemma;

    public Synsets(Lemmatizer lemma) {
        this.lemma = lemma;
    }

    List<Synset> getHypernyms(String conceptWord, String partOfSpeech) {
        final Lemma lemma = lemma.lemmatize(conceptWord);
        final List<Synset> synsets = new LinkedList<>(WordNet.synsets(conceptWord, partOfSpeech));

        final Set<String> alreadySeen = new HashSet<>();
        while (!synsets.isEmpty()) {
            final Synset synset = synsets.remove(0);
            alreadySeen.add(synset.name());

            synsets.removeAll(synset.hypernyms());
            synsets.addAll(synset.hyponyms());
            synsets.addAll(synset.instanceHyponyms());

            final String lemmatizedName = lemma.lemmatize(synset.name()).get(0);
            if (!alreadySeen.contains(lemmatizedName) && !synsets.contains(WordNet.synset(lemmatizedName))) {
                synsets.add(WordNet.synset(lemmatizedName));
            }
        }

        return synsets;
    }
}

class Lemmatizer {
    private LanguageIdentifier languageIdentifier = new LanguageIdentifier();

    public List<String> lemmatize(String word) {
        final List<String> allLemmata = new ArrayList<>();

        try (final InputStream modelStream = Lemmatizer.class.getResourceAsStream("nlp-models/lemmatizer.ser")) {
            final LemmatizerModel lemmatizerModel = new ObjectInputStream(modelStream).readObject();

            final String language = languageIdentifier.getId(word).split("-")[0];
            final LemmatizerRemapped lemmatizerRemapped = new LemmatizerRemapped(lemmatizerModel, language);

            while (word.length() > 0) {
                final List<String> lemmataForWord = lemmatizerRemapped.lemmatize(word);
                if (!lemmataForWord.isEmpty()) {
                    allLemmata.addAll(lemmataForWord);
                }
                final int lastSpaceIndex = word.lastIndexOf(' ');
                if (lastSpaceIndex == -1) {
                    break;
                }
                word = word.substring(lastSpaceIndex + 1);
            }
        } catch (final IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }

        return allLemmata;
    }
}

