public class LargestElementRecursion {

    // Define a method to find the largest element in a list recursively
    public static int FindLargest(List<int> lst) {

        // Base case: If the list is empty, return null
        if (lst.Count == 0) {
            return 0;
        }

        // Recursive case: Find the maximum element in the list by comparing the first element 
