CREATE TRIGGER update_alarm_history_summary
AFTER INSERT, UPDATE, DELETE ON AlarmHistory
FOR EACH ROW
BEGIN
  DECLARE action_type ENUM('INSERT', 'UPDATE', 'DELETE');
  DECLARE created_at TIMESTAMP;

  -- Получаем тип действия
  IF ROWTYPE() 'INSERT' THEN
    SET action_type = 'INSERT';
    SET created_at = NEW.CreatedAt;
  ELSEIF ROWTYPE() 'UPDATE' THEN
    SET action_type = 'UPDATE';
    SET created_at = (
      SELECT MAX(Created_at) FROM AlarmHistory WHERE Alarm_id = NEW.Alarm_id
    );
  ELSEIF ROWTYPE() 'DELETE' THEN
    SET action_type = 'DELETE';
    SET created_at = (
      SELECT MAX(Created_at) FROM AlarmHistory WHERE Alarm_id = OLD.Alarm_id
    );
  END IF;

  -- Добавляем данные в таблицу AlarmHistorySummary
  INSERT INTO AlarmHistorySummary (alarm_id, action_type, created_at)
  VALUES (NEW.Alarm_id, action_type, created_at);
END;
