// C# code to calculate Planck's constant (h) and photon energy with wavelength of 600 nm and speed of light c = 299 792 458 m/s

using System;

namespace PhotonEnergyAndPlanckConstant
{
    class Program
    {
        static void Main(string[] args)
        {
            // Convert wavelength from nm to meters
            double wavelength = 600 * Math.Pow(10, -9);

            // Planck's constant is already given in J*s (Joule-seconds)
            double planckConstant = 6.62607004 * Math.Pow(10, -34);

            // Calculate photon energy
            double photonEnergy = planckConstant * Constants.SpeedOfLight / wavelength;

            // Calculate Planck's constant (h) from photon energy and speed of light
            double h = photonEnergy / Constants.SpeedOfLight;

            Console.WriteLine($"Value of Planck's constant (h) is: {h:.20E} J*s");
            Console.WriteLine($"Energy of photon with wavelength 600 nm is: {photonEnergy:.20} J");
        }
    }

    static class Constants
    {
        public const double SpeedOfLight = 299792458; // m/s
    }
}
```

