   // 2. Read CSV data and convert columns to numeric types
   val data = Source.fromFile("business_owners_data.csv").getLines().drop(1)
         .map(line => line.split(",").map(_.trim.toDouble))

   // 3. Impute missing values using mean
   def impute(df: Array[Array[Double]]): Array[Array[Double]] = {
     df.map(row =>
       row.map(value =>
         if (value == 0) mean(row.filter(_ != 0)) else value
       ))
   }

   val imputedData = impute(data)
   ```

   Если вы хотите использовать другую стратегию упsertа/восстановления пропущенных значений, просто реализуйте свою функцию в данном месте кода.

4. Обработайте смещение: для этого вы можете использовать техники балансировки данных, которые позволяют пересекать подмножества данных, чтобы снизить пропорциональность негомогенности в них (гомо-генность). В данном случае вам необходимо будет выполнить следующие шаги:

   1. Визуализируйте вашу данные с помощью визуализации гистограмм, ковап (контурный анализ предсказаний), или любого другого инструмента, который вам поможет определить важные характеристики, на которых могут наблюдаться смещения.

   2. Для каждой потенциально смещенной характеристики рассмотрите несколько стратегий балансировки данных, которые могут подойти:

      - Уменьшение веса: Уменьшить вес (приоритет) наблюдений для подмножества, которое в большей степени отвечает одной из классификаций. Логично будет уменьшать вес в соответствии с отличием от репрезентативной доли класса в подмножестве, содержащем все данные.

      - Отбор: Выбирайте наблюдения, которые в большей степени похожи на репрезентативный дизбаланс. При отборе можно рассматривать те наблюдения в подмножестве, которые наиболее емки в уникальных характеристиках, отличающихся от тех, что наблюдаются в других наблюдениях.

      - Генерация: Cгенерируйте новые данные, ведущие к увеличению представительства в подмножестве наблюдений, которые показываются в дисбаланс, в соответствии с реконфигурацией результатов, которая находит целевой дизбаланс в интервале валидных значений.

   3. Вставляйте свои балансировщики в код. 

      ```scala
      import breeze.linalg.{sum, diag, Vector}
      import scala.math.pow
      import org.scalanlp.util.Implicits._ 

      // ...

      import breeze.linalg._

      type Sample = Array[Double]

      case class FeatureBalancing(
        featName: Int,
        featValues: Map[Double, Double]
      )

      def featureBalancing(df: Array[Array[Double]]): Seq[FeatureBalancing] = {
        df
          .transpose
          .zipWithIndex
          .map {
            case (values, featId) =>
              val valuesMap = values.groupMap(_)(_).mapValues(sum)
              val featProp = values.length.toDouble / df.length
              val maxPropDiff = valuesMap.maxBy(_._2._2) match {
                case Some((value, (count, prop))) =>
                  math.abs(prop - featProp)
                case None =>
                  featProp // if there no unique values, assume it's uniformly distributed
              }
              FeatureBalancing(featId, valuesMap.view.mapValues(_._1).toMap)
          }
          .filter { case FeatureBalancing(_, _) => maxPropDiff > 0.05 } // adjust threshold here
      }

      def SyntheticSampleGenerator(metric: (Sample, Sample) => Double, featBalancing: FeatureBalancing) {
        // implementation of generative (synthetic data) approach
        // given a metric to measure difference between samples (e.g. Cosine distance)
        // and a feature balancing strategy (e.g. Oversampling in a given feature range)
        // generate new samples until desired distribution is reached
      }

      def UndersamplingSelector(metric: (Sample, Sample) => Double, featBalancing: FeatureBalancing) {
        // implementation of selective (undersampling) approach
        // given a metric to measure difference between samples (e.g. Cosine distance)
        // and a feature balancing strategy (e.g. Removing samples with high feature value)
        // select a subset of the original sample maintaining feature balancing principles
      }

      def BalancingStrategy(
        strategy: String,
        metric: (Sample, Sample) => Double,
        featBalancing: FeatureBalancing
      ): Array[Array[Double]] = {
        df.groupBy(row => row(featBalancing.featName)).map {
          case (featValue, rowsWithFValue) =>
            rowsWithFValue.toList match {
              case rows if rows.length <= featBalancing.featValues(featValue) =>
                rows.map(row => row.*: featValue.double)
              case _ =>
                strategy match {
                  case "synthetic" =>
                    val synthRows = List.fill(featBalancing.featValues(featValue) - rows.length)(
                      SyntheticSampleGenerator(metric, featBalancing)
                    ).toArray
                    (rows ++ synthRows).map(row => row.*: featValue.double)
                  case "undersampling" =>
                    UndersamplingSelector(metric, featBalancing)(rows)
                }
            }
        }.reduce(_ ++ _)
      }

      def balanceData(data: Array[Array[Double]]): Array[Array[Double]] = {
        val featBalancings = featureBalancing(data)
        featBalancings.foreach { case FeatureBalancing(featId, featMap) =>
          println(s"Feature $featId has prop diff ${featBalancing.maxPropDiff} and ${featBalancing.featMap.size} unique values.")
        }
        featBalancings.headOption match {
          case Some(featBalancing) =>
            BalancingStrategy("synthetic", (a: Sample, b: Sample) => cosineDistance(a, b, norm = true), featBalancing)
          case _ =>
            data
        }
      }

      val balancedData = balanceData(imputedData)
      ```

      В данном примере кода рассматриваются сьюты генерации и отбора, но вы можете вставить свои реализации стратегий.

   4. Примените балансировщики к импутированным данным.

      ```
