function isCorrectlyPunctuated(sentence) {
  const tokens = sentence.split(' ');
  const isValidPunctuation = (prev, curr) => {
    if (prev === 'not' && !curr.includes(',')) {
      return true;
    } else if (prev === 'let' && curr[0] === 'a') {
      return true;
    } else if (prev.endsWith('.') && curr.startsWith(' ')) {
      return true;
    } else if (prev.endsWith('!?') && curr.startsWith(' ')) {
      return true;
    } else {
      return false;
    }
  };

  const isValidWord = (word) => word.length > 1;

  const isSentenceValid = tokens.every((_, i, arr) => {
    const prev = arr[i - 1] !== undefined ? arr[i - 1] : '';
    const curr = arr[i];
    return isValidWord(prev) && isValidWord(curr) && isValidPunctuation(prev, curr);
  });

  return isSentenceValid;
}

