        import java.util.concurrent.CountDownLatch;
        import java.util.concurrent.TimeUnit;

        import com.axis.vapix.connection.StreamingClient;
        import com.axis.vapix.connection.StreamingConnectionOptions;

        public class AxisVAPIXSample {

