```perl6
use XML::Parser;
use Text::CSV;

class CubeSolver {
  has Str $.xml-file is required;
  has Str $.algorithm is required;
  has Str %.moves;

  method BUILD {
    self.parse;
    self.solve;
  }

  method parse {
    my $parser = XML::Parser.new(
      :DataModel('Mem') # Parse XML into memory
    );

    my $csv = Text::CSV.new;

    my %solver-data;
    my @moves;

    my $current-state;
    my $current-hub;

    $parser.dispatch(sub ($, $data) {
      given $data.Str {
        when 'CENTER-PIECE' {
          $current-state = %solver-data<state><center-piece>.Clone; # clone to avoid modifying original state
        }
        when 'BASE-PIECE' {
          %solver-data<state><base> = {} unless %solver-data<state><base>.defined;
          $current-state = %solver-data<state><base>.Clone;
        }
        when 'STATE' {
          %solver-data<state> = {} unless %solver-data<state>.defined;
          %solver-data<state>{($data ~~ /<(\w+)>(.*?)<\/\1>/)[0]} = () unless (%solver-data<state>{($data ~~ /<(\w+)>(.*?)<\/\1>/)[0]}).defined;
          %solver-data{($data ~~ /<(\w+)>(.*?)<\/\1>/)[0]} = ($data ~~ /<(\w+)>(.*?)<\/\1>/)[1];
        }
        when 'SIZE' {
          %solver-data<cube-size> = $data.Int;
        }
        when 'HUB' {
          $current-hub = ($data ~~ /<(\w+)>(.*?)<\/\1>/)[0];
        }
        when 'MOVE' {
          push @moves, %;
          %(_).push: |($csv.hash(%solver-data<state>)),
                      |($csv.hash(%solver-data<state>)),
                      |($csv.hash!{$current-state.hash(~$current-hub)}),
                      $current-hub,
                      $_;
        }
      }
    });

    open my $fh, '<', self!.xml-file;
    while (my $line = $fh.get) {
      $parser.feed: $line;
    }
    $fh.close;
    $parser.finish;

    (%solver-data<state>).delete("center-piece");
    (%solver-data<state>).delete("base");

    %.moves = @moves;
  }

  method solve {
    given self!.algorithm {
      when 'hashiveara' {
        my $solver = Hashivore::Solver.new(
          cube-size => self!.%cube-size
        );

        my $start-state = Hashivore::State.new(
          colors => (1..self!.%cube-size)»*.Str,
          edges => Hashivore::Edges.new(
            { .key => Hashivore::Edge.new($.key, "U")
              for 0..(self!.%cube-size - 1) }
          ),
          corners => Hashivore::Corners.new(
            { .key => Hashivore::Corner.new($.key, "U")
              for (0..8) }
          ),
          center => self!.%solver-data<state>.hash,
          base => { .key => "" for 1..27 }
        );

        my $solution = $solver.solve($start-state);

        my @moves;
        for @($solution mv) -> $move {
          push @moves, %.moves{$move}};
        }

        say "Solution with Hashivore algorithm:";
        say @moves.join(" ");
      }
    }
  }
}

# Example usage:
my CubeSolver $solver = CubeSolver.new(
  .xml-file => 'input.xml',
  .algorithm => 'hashivoeara'
);

```

