import java.io.StringReader;

public class RubiksCubeXmlParser {

    public static CubeState toCubeState(String xmlData) {
        CubeState cubeState = new CubeState();

        try {
            SAXBuilder saxBuilder = new SAXBuilder();
            Document document = saxBuilder.build(new StringReader(xmlData));

            Element rootElement = document.getRootElement();
            Element cubeElement = rootElement.getChild("cube");

            cubeState.setColor(cubeElement.getChild("front").getChild("top").getChildText("color"));
            cubeState.setFrontTop(cubeElement.getChild("front").getChild("top").getChildText("value"));
            // continue setting other faces

        } catch (JDOMException | IOException e) {
            e.printStackTrace();
        }

        return cubeState;
    }
}
