2. Add the following code at the beginning of your `server.js` file to use the `body-parser` middleware:

    ```javascript
    const bodyParser = require('body-parser');
    app.use(bodyParser.urlencoded({ extended: true }));
    app.use(bodyParser.json());

    // Handle the root route (POST request added below)
    app.post('/', (req, res) => {
      const { message } = req.body;

      if (message) {
        res.send(`Hello, ${message}!`);
      } else {
        res.status(400).send('Please provide a message in the request body.');
      }
    });
    ```

    In this example, we assume that the `message` will be sent via the request body as a `form-data` or `JSON` format. Depending on the form submission format, the `extended` option of `urlencoded()` middleware needs to be set to `true` for nested objects or `false` for flat objects.

