\section{Анализ возмущений на основе матриц тензоров Якоби}

\begin{frame}{Анализ возмущений на основе матриц тензоров Якоби}
  \begin{block}{Фундаментальные модели системы маятника}
    \begin{itemize}
      \item Свободный маятник $(ur = 0)$
      \item В системе, где $x = 0$
    \end{itemize}
  \end{block}

  \begin{block}{Сокращение параметров}
    \begin{align*}
      \beta &= \frac{mg}{l}, \\
      \alpha &= \frac{m+M}{m}, \\
      \omega_0 &= \sqrt{\frac{\beta}{\alpha}},
    \end{align*}
  \end{block}

  \begin{block}{Система дифференциальных уравнений для фундаментальных моделей (с последующим преобразованием)}
    \begin{align}
      \ddot{\theta} + \omega_0^2 \theta &= 0 \label{eq:theta} \\
      \ddot{x} + \beta \alpha \cos{\theta} &= 0 \label{eq:x}
    \end{align}
  \end{block}

  \begin{block}{Возмущения методом Якоби}
    \begin{align*}
      \delta_{\theta} &= \theta + \Delta\theta, \\
      \delta_{x} &= x + \Delta{x},
    \end{align*}
  \end{block}

  \begin{block}{Линейнаяизмененная  система дифференциальных уравнений}
    \begin{align}
      \ddot{\theta} + \omega_0^2 \theta &= f_{\theta}(x, \theta) \\
      \ddot{x} + \beta \alpha \cos{\theta} &= f_{x}(x, \theta)
    \end{align}
    \begin{align*}
      f_{\theta}(x, \theta) &\approx \left.\frac{\partial f_{\theta}}{\partial x}\right|_{\tilde{x}} \Delta{x} + \left.\frac{\partial f_{\theta}}{\partial \theta}\right|_{\tilde{\theta}}
      \approx \beta \alpha \sin{\theta} \Delta{x} \\
      f_{x}(x, \theta) &\approx \left.\frac{\partial f_{x}}{\partial \theta}\right|_{\tilde{\theta}} \Delta{\theta} \approx - \beta \alpha \sin{\theta} \Delta{\theta}
    \end{align*}
  \end{block}

\end{frame}

