using System;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;

namespace SortBooksByPublicationDate
{
    class Program
    {
        static void Main(string[] args)
        {
            string jsonFilePath = "books.json";

            // читаем данные из файла JSON
            string jsonString = File.ReadAllText(jsonFilePath);
            BooksResponse data = JsonConvert.DeserializeObject<BooksResponse>(jsonString);

            // сортируем список книг по дате публикации
            List<Book> sortedBooks = data.Books
                .OrderBy(b => DateTime.Parse(b.PublicationDate)).ToList();

            // выводим названия книг и даты публикации
            foreach (var book in sortedBooks)
