```﻿# Решение на Java

```java
import java.io.File;
import java.io.IOException;
import java.time.LocalDate;
import java.util.Collections;
import java.util.List;

import com.fasterxml.jackson.databind.ObjectMapper;

public class SortBooksByPublicationDate {

    public static void main(String[] args) throws IOException {
        String jsonFilePath = "books.json";

        // читаем данные из файла JSON
        String jsonString = new File(jsonFilePath).getContent().toString();
        BooksResponse data = new ObjectMapper().readValue(jsonString, BooksResponse.class);

        // сортируем список книг по дате публикации
        List<Book> sortedBooks = data.getBooks()
            .stream()
            .sorted((b1, b2) -> LocalDate.parse(b1.getPublicationDate()).compareTo(LocalDate.parse(b2.getPublicationDate())))
            .toList();

        // выводим названия книг и даты публикации
        for (var book : sortedBooks) {
            System.out.printf("%s - %s%n", book.getTitle(), book.getPublicationDate());
        }
    }

    static class BooksResponse {
        private List<Book> books;

        public List<Book> getBooks() {
            return books;
        }

        public void setBooks(List<Book> books) {
            this.books = books;
        }
    }

    static class Book {
        private String title;
        private String author;
        private String publicationDate;

        public String getTitle() {
            return title;
        }

        public String getAuthor() {
            return author;
        }

        public String getPublicationDate() {
            return publicationDate;
        }

        public void setTitle(String title) {
            this.title = title;
        }

        public void setAuthor(String author) {
            this.author = author;
        }

        public void setPublicationDate(String publicationDate) {
            this.publicationDate = publicationDate;
        }
    }
}
```

В данном случае для считывания данных из JSON-файла используется библиотека Jackson. Список книг сортируется с помощью Stream API и лямбда-выражения в методе `sorted()` в сочетании с маппированием даты публикации в объект класса LocalDate (класс из библиотеки Java 8 Time API). 

Вывод названий книг и дат публикации производится в цикле.foreach(). 

Результат выполнения программы для приведенного примера будет:

```
Великий Гэтсби - 1925-04-10T00:00:00Z
1984 - 1949-06-08T00:00:00Z
Гордость и предубеждение - 1813-01-28T00:00:00Z
```﻿# Решение на Kotlin

