Одной из возможных структур данных, которая удовлетворяет требованиям, предложенных в условии, является двусвязный циклический список (Circular Doubly Linked List), поддерживающий дополнительные поля для хранения чисел разряжения при инициализации очереди.

Структура данных Node, хранящая элемент очереди и дополнительную информацию:

```python
class Node:
    def __init__(self, val):
        self.val = val
        self.prev = None
        self.next = None
        self.inv_denom = 0

    def set_inv_denom(self, pos):
        self.inv_denom = 1 / (self.next.val ** pos) if pos > 0 else 0
```

Структура данных CircularDoublyLinkedList, реализующая операции на базе списка узлов и обеспечивающая требуемую сложность операций:

```python
class CircularDoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def is_empty(self):
        return self.size == 0

    def _get_node(self, index):
        if not 0 <= index < self.size:
            raise IndexError("List index out of range")
        curr = self.head if index == 0 else self._get_node_at(index - 1).next
        for I in range(index, self.size):
            curr = curr.next
        return curr

    def _get_node_at(self, node):
        if node is self.head:
            return self.tail
        if node is self.tail:
            return self.head

        return node.prev

    def insert(self, index, val):
        if index < 0 or index > self.size:
            raise IndexError("List index out of range")
        new_node = Node(val)
        if self.is_empty():
            self.head = new_node
            self.tail = new_node
            new_node.prev = new_node.next = new_node
        else:
            if index == 0:
                new_node.next = self.head
                new_node.prev = self.tail
                self.head.prev = new_node
                self.tail.next = new_node
                if self.size % 2 == 0:
                    self._update_inv_denoms(new_node, 1)
            elif index == self.size:
                new_node.prev = self.tail
                new_node.next = self.head
                self.tail.next = new_node
                self.head.prev = new_node
                if (self.size - 1) % 2 == 1:
                    self._update_inv_denoms(self._get_node_at(new_node), -1)
            else:
                prev_node = self._get_node_at(index - 1)
                new_node.next = prev_node.next
                new_node.prev = prev_node
                prev_node.next.prev = new_node
                prev_node.next = new_node
                if (index - 1) % 2 == 0 and index % 2 == 1:
                    self._update_inv_denoms(new_node, 1)
                    self._update_inv_denoms(prev_node.next, -1)
        self.size += 1

    def _update_inv_denoms(self, curr_node, delta):
        curr_node.inv_denom += delta * curr_node.prev.inv_denom * curr_node.next.val
        if self.head is not curr_node:
            self._update_inv_denoms(curr_node.prev, delta)

    def remove(self, index):
        if index < 0 or index >= self.size:
            raise IndexError("List index out of range")
        removed_node = self._get_node(index)
        if index == 0:
            self.head = removed_node.next
            self.head.prev = self.tail
            self.tail.next = self.head
            if self.size % 2 == 1:
                self._update_inv_denoms(removed_node.next, 1)
        elif index == self.size - 1:
            self.tail = removed_node.prev
            self.tail.next = self.head
            self.head.prev = self.tail
            if self.size % 2 == 1:
                self._update_inv_denoms(self._get_node_at(removed_node), -1)
        else:
            removed_node.prev.next = removed_node.next
            removed_node.next.prev = removed_node.prev
            if (index - 1) % 2 == 0 and index % 2 == 1:
                self._update_inv_denoms(removed_node.next, 1)
                self._update_inv_denoms(removed_node.prev, -1)
        self.size -= 1

    def see_saw(self):
        if self.is_empty():
            return 0
        inv_sum = self.head.inv_denom
        curr = self.head.next
        for I in range(1, self.size):
            inv_sum += curr.inv_denom
            curr = curr.next
        return inv_sum

    def __len__(self):
        return self.size
```

Пользовательский интерфейс:

```python
