class BalancedQueue {
private:
    // std::deque, основная структура данных,backed by a contiguous array, which allows for efficient push and pop operations.
    std::deque<std::pair<int, T>> queue;
    int total_count; // To keep track of the total number of elements in the queue
    int leading_count; // To keep track of the number of elements in the left part of the seesaw

