        queue.push_back({1, elem}); // Add a new element to the right of the seesaw
    }

    // Pop elements from the queue
    void pop() {
        assert(!queue.empty());
        total_count--;
        queue.pop_front(); // Remove the leftmost element from the queue
    }

    // Return the element at the front of the queue without removing it
    T front() const {
        assert(!queue.empty());
        return queue.front().second;
    }

    // Check if the queue is empty
    bool empty() const {
        return queue.empty();
    }

    // Return the size of the queue
    size_t size() const {
        return total_count - leading_count;
    }

    // Perform the seesaw operation
    double seeSaw() {
        assert(!queue.empty()); // Queue should not be empty
        while (!queue.empty() && queue.front().first == 1) { // Keep removing elements from the left until a / operator is encountered
            leading_count++;
            pop();
