        double result = 0;
        while (!queue.empty() && queue.front().first == -1) { // Keep adding elements to the result until a + operator is not encountered
            result += static_cast<double>(queue.front().second) / static_cast<double>(leading_count);
            pop();
        }

        while (!queue.empty() && queue.front().first == 1) { // Keep removing elements from the left, because the seeSaw operation is done
            pop();
        }

        return result;
    }
};
