// файл plugins/comprehensible-vue/rules/comprehensible-vue-stateless-hooks.js:

export default {
  meta: {
    type: 'suggestion',
    docs: {
      description: 'Prevent state changing methods from being called directly in lifecycle hooks',
      category: 'Vue.js',
    },
    fixable: 'code',
    schema: [],
  },

  create(context) {
    return {
      'ScopedSlot': (node) => {
        checkStatelessMethods(
          node,
          ['created', 'mounted', 'beforeUpdate', 'updated'],
          context
        )
      },
      'templateElement': (node) => {
        checkStatelessMethods(node, ['beforeCreate', 'created'], context)
      },
    }
  },
}

function checkStatelessMethods(node, lifecycleHooks, context) {
  const { methods } = node

  if (!methods) {
    return
  }

  lifecycleHooks.forEach((hook) => {
    if (!methods[hook]) {
      return
    }

    const methodName = methods[hook].key.name

    context.report({
      node,
      message: `Lifecycle hook "${hook}" should not call a method that updates component state directly. Method "${methodName}" should not manipulate the component's internal state.`,
      fix(fixer) {
        return fixer.removeRange([methods[hook].range[0], methods[hook].range[1]])
      },
    })

    const methodsCalled = getMethodsCalled(methods[hook].body)

    if (methodsCalled.some((method) => isStateChangingMethod(methodCache, method))) {
      context.report({
        node,
        message:
          'Lifecycle hook "'+
          hook+
          '" must not call a method that directly modifies component state. ' +
          'The called method "' +
          methodsCalled.find((method) => isStateChangingMethod(methodCache, method)).name +
          '" modifies the component\'s internal state.',
      })
    }
  })
}

const methodCache = new Map()

function isStateChangingMethod(methodCache, methodNameAst) {
  const methodName = methodNameAst.name
  if (!methodCache.has(methodName)) {
    const { declarations } = getDeclaration(methodNameAst)
    methodCache.set(methodName, declarations.some((declaration) => {
      const { expressions } = declaration.value
      return expressions.some((expression) => {
        if (expression.callee) {
          const { name: calleeName } = expression.callee
          return (
            calleeName === 'this' ||
            STATE_MODIFYING_METHODS.includes(calleeName)
          )
        }
        return false
      })
    }))
  }
  return methodCache.get(methodName)
}

function getDeclaration(node) {
  if (node.parent.type === 'ReturnStatement') {
    const { expressions } = node.parent.argument
    return getDeclaration(expressions[0])
  } else if (node.parent.type === 'AssignmentExpression') {
    return {
      declarations: [node],
    }
  }
  return {
    declarations: [],
  }
}

const STATE_MODIFYING_METHODS = ['push', 'pop', 'shift', 'unshift', 'splice', 'sort', 'reverse']

function getMethodsCalled(node) {
  if (node.type !== 'BlockStatement') {
    return [node]
  }
  return node.body.filter((item) => item.type === 'ExpressionStatement').map((item) => item.expression)
}
